import React, { useState } from 'react';
import { 
  Trash2, Map, Calendar, Star, LineChart, Users, 
  HardHat, FileText, ChevronRight, Activity, 
  Search, Filter, ShieldAlert, AlertCircle 
} from 'lucide-react';

const Dashboard = () => {
  const [activeTab, setActiveTab] = useState('BINS');

  const allTabs = [
    { id: 'BINS', label: '01_BIN_MONITORING', icon: <Trash2 size={20}/> },
    { id: 'ZONES', label: '02_AREAS_&_ZONES', icon: <Map size={20}/> },
    { id: 'SCHEDULE', label: '03_COLL_SCHEDULE', icon: <Calendar size={20}/> },
    { id: 'POINTS', label: '04_REWARDS_POINTS', icon: <Star size={20}/> },
    { id: 'ANALYTICS', label: '05_SYS_ANALYTICS', icon: <LineChart size={20}/> },
    { id: 'CITIZENS', label: '06_CITIZEN_INFO', icon: <Users size={20}/> },
    { id: 'WORKERS', label: '07_WORKER_NODES', icon: <HardHat size={20}/> },
    { id: 'REPORTS', label: '08_SYS_REPORTS', icon: <FileText size={20}/> },
  ];

  return (
    <div className="w-full max-w-[1000px] flex flex-col gap-5 p-6 animate-slot">

      {/* BLOCK 1: THE BRANDED HEADER (BEET RED) */}
      <div className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-t-[50px] rounded-b-[15px] p-6 red-stack-shadow relative overflow-hidden">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-5">
            <div className="bg-[#FDFAD8] p-3 rounded-xl border-4 border-[#47510B] shadow-[4px_4px_0_0_#47510B]">
              <ShieldAlert size={32} className="text-[#AB1717]" strokeWidth={2.5} />
            </div>
            <div>
              <p className="text-[10px] font-black uppercase tracking-[0.4em] text-[#FDFAD8] opacity-70 italic leading-none mb-1 text-left">Admin.Command.Center</p>
              <h1 className="text-3xl font-black italic tracking-tighter text-[#FDFAD8] uppercase">
                TRASH<span className="text-[#CAD23C]">2</span>TRACK
              </h1>
            </div>
          </div>
          <div className="text-right flex flex-col items-end">
            <Activity className="text-[#CAD23C] animate-pulse mb-1" size={24} />
            <span className="text-[10px] font-black text-[#FDFAD8] opacity-40 uppercase">System_v3.0</span>
          </div>
        </div>
      </div>

      {/* BLOCK 2: THE MECHANICAL SELECTOR TRAY (BLUE-GREY) */}
      <div className="bg-[#A1AED1] border-[6px] border-[#47510B] rounded-[25px] p-4 yellow-stack-shadow relative">
        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-[#AB1717] mb-3 ml-4">Select_Operation_Module</p>

        {/* Horizontal Scrolling Switcher */}
        <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar px-2">
          {allTabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`
                flex-shrink-0 flex items-center gap-3 px-6 py-4 rounded-[20px] border-[4px] border-[#47510B] font-black text-xs uppercase transition-all
                ${activeTab === tab.id 
                  ? 'bg-[#CAD23C] text-[#47510B] shadow-none translate-y-1' 
                  : 'bg-[#FDFAD8] text-[#AB1717] shadow-[4px_4px_0_0_#47510B] hover:translate-y-0.5'}
              `}
            >
              {tab.icon}
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* BLOCK 3: THE MAIN DISPLAY SCREEN (BEET RED CONTAINER) */}
